/**
 * "Set packages & monthly fee" / "Generate this month's bills" (#248).
 *
 * Quick Collect and Bulk Collect only list customers with a pending balance. With the bundled
 * roster nobody has a package or monthly fee yet, so no bill exists and nothing is pending.
 * The empty state offers two actions, handled here:
 *  - Set packages & monthly fee: pick a package (or a custom fee) and the customers without a
 *    fee; saved through core updateCustomerProfile (same as the profile form, keeps package
 *    history), then this month's bills are generated by the core generator.
 *  - Generate this month's bills: runs core generateMonthlyBillsThroughCurrentMonth.
 * Everything is saved through Quick Collect's commitState (the app's normal save path).
 */
import { updateCustomerProfile, generateMonthlyBillsThroughCurrentMonth } from './core.js';
import { BILL_PACKAGES } from './package-catalog.js';
import { customerHasMonthlyFee } from './nav-quick-collect.js';

const countBills = state => (state?.customers ?? []).reduce((n, c) => n + (c.bills?.length ?? 0), 0);

/** Active customers with no package / monthly fee. */
export function customersWithoutFee(state) {
  return (state?.customers ?? []).filter(c => !c.archived && !customerHasMonthlyFee(c));
}

/** Generate any due monthly bills. Returns { nextState, generated }. */
export function generateBillsNow(state, referenceDate = new Date()) {
  const nextState = generateMonthlyBillsThroughCurrentMonth(state, referenceDate);
  return { nextState, generated: countBills(nextState) - countBills(state) };
}

/**
 * Give `customerIds` a package (by id from BILL_PACKAGES) or a custom monthly fee, then
 * generate their bills. Returns { nextState, updated, generated }.
 */
export function assignPackage(state, customerIds, { packageId = '', fee = null, staffName = '' } = {}, referenceDate = new Date()) {
  const plan = packageId ? BILL_PACKAGES.find(p => p.id === packageId) : null;
  if (packageId && !plan) throw new Error('Choose one of the available packages.');
  const amount = plan ? plan.price : Number(fee);
  if (!Number.isFinite(amount) || amount <= 0) throw new Error('Choose a package or enter a monthly fee greater than zero.');
  const ids = [...new Set(customerIds)].filter(Boolean);
  if (!ids.length) throw new Error('Select at least one customer.');
  let next = state;
  for (const id of ids) {
    const values = { monthlySellingAmount: amount, packageChangeStaffName: staffName || 'Quick Collect setup' };
    if (plan) values.packageSpeed = plan.label;
    next = updateCustomerProfile(next, id, values, referenceDate);
  }
  const { nextState, generated } = generateBillsNow(next, referenceDate);
  return { nextState, updated: ids.length, generated };
}

/* ------------------------------------------------------------------ UI ------------------ */

const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));

export function setupCollectSetup({ win = window, doc = document, getController = () => win.quickCollectModalController } = {}) {
  if (doc.getElementById('collectSetupModal')) return win.collectSetup;
  const wrap = doc.createElement('div');
  wrap.innerHTML = `
  <dialog id="collectSetupModal" class="modal collect-setup-modal" aria-labelledby="collectSetupTitle">
    <section class="collect-setup-card">
      <div class="modal-heading">
        <div><p class="eyebrow">BILLING SETUP</p><h2 id="collectSetupTitle">Set packages &amp; monthly fee</h2></div>
        <button id="closeCollectSetupBtn" class="close-button" type="button" aria-label="Close package setup">×</button>
      </div>
      <p class="cs-note">Customers without a package/fee get no bill, so they never show as pending. Pick a package for the selected customers; this month's bill is created right away.</p>
      <div class="cs-grid">
        <label class="bc-field">Package
          <select id="collectSetupPackage">
            ${BILL_PACKAGES.map(p => `<option value="${esc(p.id)}">${esc(p.label)} · PKR ${p.price.toLocaleString('en-PK')}</option>`).join('')}
            <option value="">Custom monthly fee…</option>
          </select>
        </label>
        <label class="bc-field" id="collectSetupFeeLabel" hidden>Monthly fee (PKR)
          <input id="collectSetupFee" type="number" inputmode="decimal" min="1" step="1">
        </label>
      </div>
      <div class="cs-list-head">
        <label class="cs-select-all"><input id="collectSetupSelectAll" type="checkbox"> Select all</label>
        <span id="collectSetupCount">0 selected</span>
      </div>
      <input id="collectSetupSearch" class="qc-search-input" type="search" placeholder="Search name, mobile or area…" aria-label="Search customers without a fee">
      <div id="collectSetupList" class="cs-list" role="group" aria-label="Customers without a package or fee"></div>
      <p id="collectSetupStatus" class="bc-status" role="status" aria-live="polite" hidden></p>
      <button id="collectSetupApplyBtn" class="primary-button cs-apply" type="button" disabled>Apply: Set package &amp; generate bills</button>
    </section>
  </dialog>`;
  doc.body.appendChild(wrap.firstElementChild);
  const $ = id => doc.getElementById(id);
  const modal = $('collectSetupModal');
  const pkg = $('collectSetupPackage');
  const fee = $('collectSetupFee');
  const list = $('collectSetupList');
  const search = $('collectSetupSearch');
  const selectAll = $('collectSetupSelectAll');
  const applyBtn = $('collectSetupApplyBtn');
  const status = $('collectSetupStatus');
  let checked = new Set();

  const state = () => getController()?.getState?.();
  const say = (msg, kind = 'info') => { status.textContent = msg; status.dataset.kind = kind; status.hidden = !msg; };
  const visibleCustomers = () => {
    const q = search.value.trim().toLowerCase();
    return customersWithoutFee(state()).filter(c => !q || [c.name, c.phone, c.area, c.mohalla, String(c.customerNumber)].some(v => String(v ?? '').toLowerCase().includes(q)));
  };
  function render() {
    const rows = visibleCustomers();
    list.innerHTML = rows.length ? rows.map(c => `
      <label class="cs-row"><input type="checkbox" data-cs-customer="${esc(c.id)}" ${checked.has(c.id) ? 'checked' : ''}>
        <span><strong>#${esc(c.customerNumber)} ${esc(c.name)}</strong><small>${esc(c.area || 'Unassigned')}${c.phone ? ' · ' + esc(c.phone) : ''}</small></span></label>`).join('')
      : '<p class="cs-empty">Every customer has a package / monthly fee.</p>';
    $('collectSetupCount').textContent = `${checked.size} selected`;
    selectAll.checked = rows.length > 0 && rows.every(c => checked.has(c.id));
    applyBtn.disabled = checked.size === 0;
    applyBtn.textContent = checked.size ? `Apply: Set package for ${checked.size} & generate bills` : 'Apply: Set package & generate bills';
  }
  pkg.addEventListener('change', () => { $('collectSetupFeeLabel').hidden = pkg.value !== ''; });
  search.addEventListener('input', render);
  selectAll.addEventListener('change', () => {
    for (const c of visibleCustomers()) { if (selectAll.checked) checked.add(c.id); else checked.delete(c.id); }
    render();
  });
  list.addEventListener('change', e => {
    const box = e.target.closest('[data-cs-customer]');
    if (!box) return;
    const id = box.getAttribute('data-cs-customer');
    if (box.checked) checked.add(id); else checked.delete(id);
    render();
  });
  applyBtn.addEventListener('click', () => {
    const controller = getController();
    try {
      const { nextState, updated, generated } = assignPackage(state(), [...checked], { packageId: pkg.value, fee: fee.value });
      controller.commitState(nextState);
      checked = new Set();
      render();
      const msg = `✓ Package set for ${updated} customer${updated === 1 ? '' : 's'} · ${generated} bill${generated === 1 ? '' : 's'} generated. They now show in Quick Collect.`;
      say(msg, 'success');
      win.bulkCollect?.refresh?.();
      controller?.refresh?.();
      if (typeof win.toast === 'function') win.toast(msg);
    } catch (err) {
      say(err.message, 'error');
    }
  });
  $('closeCollectSetupBtn').addEventListener('click', () => modal.close());
  modal.addEventListener('close', () => { getController()?.refresh?.(); win.bulkCollect?.refresh?.(); });

  function open() {
    checked = new Set();
    search.value = '';
    say('');
    render();
    try { if (!modal.open) modal.showModal(); } catch { modal.setAttribute('open', ''); }
  }

  function generate(statusTarget) {
    const controller = getController();
    const st = state();
    if (!st || !controller?.commitState) return;
    const { nextState, generated } = generateBillsNow(st);
    if (generated > 0) controller.commitState(nextState);
    const msg = generated > 0
      ? `✓ ${generated} bill${generated === 1 ? '' : 's'} generated for this month.`
      : 'No new bills: customers need a package / monthly fee first.';
    if (statusTarget) { statusTarget.textContent = msg; statusTarget.hidden = false; }
    win.bulkCollect?.refresh?.();
    if (typeof win.toast === 'function' && generated > 0) {
      win.toast(msg);
    }
  }

  // Delegated: the buttons live in Quick Collect's / Bulk Collect's empty states.
  doc.addEventListener('click', e => {
    if (e.target.closest('[data-qc-setup-packages]')) { e.preventDefault(); open(); }
    const gen = e.target.closest('[data-qc-generate-bills]');
    if (gen) {
      e.preventDefault();
      const host = gen.closest('.qc-empty-state');
      let note = host?.querySelector('.qc-generate-result');
      if (host && !note) { note = doc.createElement('p'); note.className = 'qc-generate-result'; note.setAttribute('role', 'status'); host.appendChild(note); }
      generate(note);
    }
  });

  const api = { open, generate, close: () => modal.close() };
  win.collectSetup = api;
  return api;
}

if (typeof window !== 'undefined' && typeof document !== 'undefined' && document.body) {
  setupCollectSetup();
}
